USE health_ai_platform;

-- ============================================================
-- Real policy content for the 5 core Facility & Providers
-- knowledge_docs (v1/v2/v3 of each = 15 rows total), replacing
-- the Faker gibberish generated by generate_seed_data.py.
-- ============================================================

-- --- Provider Credentialing SOP -----------------------------
UPDATE knowledge_docs SET content = 'New providers must complete primary source verification before being added to the network: active license verification through the state medical board, NPI registry confirmation, malpractice insurance certificate (minimum coverage thresholds per specialty), OIG/SAM exclusion list screening, and a minimum of three years of clean malpractice history (or a documented explanation for any claims). Credentialing must be completed within 90 days of application receipt; providers remain in PENDING_CREDENTIALING status throughout this process and cannot bill as in-network until credentialing is complete and network_status is updated to IN_NETWORK. Re-credentialing is required every 3 years for all active network providers, using the same verification steps as initial credentialing.'
WHERE dept_id = 6 AND title = 'Provider Credentialing SOP';

UPDATE knowledge_docs SET content = 'Revision 2 shortens the standard credentialing window in v1 from 90 to 60 days for providers joining an existing in-network group practice (since the practice''s facility-level credentialing already covers much of the verification), while solo/independent providers remain on the 90-day standard. This revision also adds a provisional credentialing option: a provider with all verification complete except pending malpractice history documentation may be granted provisional IN_NETWORK status for up to 30 days while that single item is finalized, rather than remaining fully PENDING_CREDENTIALING.'
WHERE dept_id = 6 AND title = 'Provider Credentialing SOP v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds telehealth-specific credentialing criteria: providers offering telehealth-only services must additionally verify licensure in every state where they will see members (not just their primary practice state), reflecting multi-state telehealth practice patterns not addressed in v1 or v2. This revision also formalizes the re-credentialing cycle from v1 as risk-based rather than strictly 3-year for all providers — providers with any malpractice claim or member complaint in the prior cycle are re-credentialed at 2 years instead of 3.'
WHERE dept_id = 6 AND title = 'Provider Credentialing SOP v3';

-- --- Network Adequacy Standards -----------------------------
UPDATE knowledge_docs SET content = 'Network adequacy is measured per specialty and per county using two standards: time/distance (a member must have an in-network provider of each core specialty within 30 minutes or 15 miles in urban counties, 60 minutes or 30 miles in rural counties) and appointment wait time (routine appointments available within 10 business days, urgent within 48 hours). Counties failing either standard for a given specialty trigger an active recruitment effort for that specialty in that county, tracked separately from routine credentialing volume. Adequacy is reassessed quarterly using current network_status and address data, not just at initial network design.'
WHERE dept_id = 6 AND title = 'Network Adequacy Standards';

UPDATE knowledge_docs SET content = 'Revision 2 adds behavioral health as a specialty category with its own, stricter standard from v1''s general framework: 20 minutes/10 miles urban and 45 minutes/20 miles rural, reflecting regulatory guidance that behavioral health access gaps have outsized impact on member outcomes. This revision also adds a telehealth adequacy credit: a county may count telehealth-available providers toward adequacy for specific specialties (psychiatry, certain specialist consults) where telehealth delivery is clinically appropriate, reducing but not eliminating the in-person density requirement.'
WHERE dept_id = 6 AND title = 'Network Adequacy Standards v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds a member-complaint trigger independent of the quarterly reassessment cycle in v1: three or more member complaints about access difficulty for the same specialty in the same county within any 90-day window automatically triggers an out-of-cycle adequacy review, rather than waiting for the next quarterly cycle. This revision also clarifies that a PENDING_CREDENTIALING provider does not count toward adequacy until network_status reaches IN_NETWORK, closing a gap where in-progress credentialing was being counted as available access.'
WHERE dept_id = 6 AND title = 'Network Adequacy Standards v3';

-- --- Contract Renewal Checklist -----------------------------
UPDATE knowledge_docs SET content = 'Provider contracts are reviewed for renewal 120 days before contract_end. The renewal checklist covers: current credentialing status confirmation, claims/quality performance review for the expiring term, fee schedule alignment with the current Fee Schedule Update Policy, and any network adequacy considerations (a low-adequacy specialty/county combination weighs toward renewal even with mixed performance history). A contract not renewed by contract_end automatically moves the provider to OUT_OF_NETWORK status — there is no grace period for contract lapses the way there is for member premium payments.'
WHERE dept_id = 6 AND title = 'Contract Renewal Checklist';

UPDATE knowledge_docs SET content = 'Revision 2 extends the renewal review window in v1 from 120 to 150 days for facility-level contracts specifically (hospitals, surgical centers), since these negotiations typically take longer than individual provider renewals and a 120-day window was found to frequently run past contract_end before terms were finalized. This revision also adds an auto-extension provision: if a renewal is under active negotiation in good faith at contract_end, the existing terms extend automatically for up to 30 days rather than the provider immediately lapsing to OUT_OF_NETWORK.'
WHERE dept_id = 6 AND title = 'Contract Renewal Checklist v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds a performance-tiered renewal fast-track: providers in the top quality/performance tier for two consecutive contract terms may renew via an abbreviated checklist (skipping the full quality re-review in v1) unless a network adequacy or fee schedule change specifically requires fuller review. This revision also requires that any renewal resulting in a network_status change be logged with the specific checklist items that drove the decision, matching the documentation standard used elsewhere in this platform for write-offs and adjudication decisions.'
WHERE dept_id = 6 AND title = 'Contract Renewal Checklist v3';

-- --- Facility Termination Process -----------------------------
UPDATE knowledge_docs SET content = 'A provider or facility may be terminated from the network for cause (credentialing failure, quality/safety concerns, fraud investigation) or without cause (business decision, contract non-renewal). For-cause terminations require documented evidence and, for licensed individual providers, due process consistent with peer review protections — the provider must be notified of specific concerns and given an opportunity to respond before termination is finalized. Without-cause terminations require 90 days advance written notice per standard contract terms. In both cases, members actively receiving care from the terminated provider are entitled to continuity-of-care coverage at in-network rates for a transition period, typically 90 days or until the episode of care concludes, whichever is shorter.'
WHERE dept_id = 6 AND title = 'Facility Termination Process';

UPDATE knowledge_docs SET content = 'Revision 2 adds an immediate-suspension path for for-cause terminations in v1 involving an active patient safety risk: rather than completing the full due-process notification-and-response cycle before any status change, the provider may be immediately suspended (network_status set to TERMINATED) pending the due process review, with the review completed within 30 days to either confirm or reverse the suspension. This revision also extends the continuity-of-care window in v1 from a flat 90 days to the full course of an active pregnancy or oncology treatment regardless of length, given the clinical risk of care disruption in those specific circumstances.'
WHERE dept_id = 6 AND title = 'Facility Termination Process v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds a formal appeal path for without-cause terminations, which v1 and v2 treated as non-appealable business decisions: a provider may request reconsideration within 30 days of a without-cause termination notice, reviewed by a committee not involved in the original decision, though the 90-day notice period in v1 continues to run during the appeal rather than pausing. This revision also requires that member notification of any termination (for-cause or without-cause) include specific continuity-of-care instructions, not just the fact of termination, since member confusion about ongoing care access was identified as a common post-termination complaint.'
WHERE dept_id = 6 AND title = 'Facility Termination Process v3';

-- --- Fee Schedule Update Policy -----------------------------
UPDATE knowledge_docs SET content = 'Fee schedules are updated annually, effective January 1, based on a blend of CMS Medicare fee schedule changes and regional cost-of-care adjustments. Providers are notified of fee schedule changes at least 60 days before the effective date. Mid-year fee schedule changes are reserved for specific triggers: a new CPT/HCPCS code requiring a rate assignment, a significant regional cost anomaly, or a negotiated rate change tied to a specific contract renewal. A provider disputing a specific rate assignment may request a rate review, which does not pause billing at the current published rate while under review.'
WHERE dept_id = 6 AND title = 'Fee Schedule Update Policy';

UPDATE knowledge_docs SET content = 'Revision 2 shortens the standard notification window in v1 from 60 to 45 days for decreases only (rate increases retain the 60-day window), since providers generally need less lead time to adjust operations for a rate increase than a decrease. This revision also adds a specialty-specific phase-in option for large fee schedule decreases (greater than 10% year-over-year): the decrease may be phased in over two annual cycles rather than applied all at once, at the plan''s discretion, to reduce network disruption risk.'
WHERE dept_id = 6 AND title = 'Fee Schedule Update Policy v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds a value-based adjustment layer on top of the standard annual update in v1: providers meeting defined quality benchmarks (from the same performance review referenced in the Contract Renewal Checklist) receive a rate adjustment on top of the standard annual fee schedule change, rather than all providers in a specialty receiving an identical flat rate. This revision also formalizes the rate-review process in v1 with a defined 30-day response SLA, since providers had previously reported rate reviews going unanswered for extended periods.'
WHERE dept_id = 6 AND title = 'Fee Schedule Update Policy v3';
